const tracks=[{title:'Sunset Drive',artist:'Lofi Chill',art:'sunset',icon:'☀',hz:261.63},{title:'Golden Hour',artist:'JVKE',art:'golden',icon:'✦',hz:293.66},{title:'Coffee Shop',artist:'Beabadoobee',art:'coffee',icon:'☕',hz:329.63},{title:'Lavender Dreams',artist:'Melody Studio',art:'sunset',icon:'☾',hz:349.23},{title:'Sunday Morning',artist:'Soft Notes',art:'golden',icon:'♫',hz:392}];
const $=s=>document.querySelector(s);let expanded=false,tab='Dashboard',liked=new Set(),current=null,isPlaying=false,seconds=0,audio,voices=[],gain,timer;let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function render(){const query=$('#search').value.toLowerCase();const items=tracks.filter((t,i)=>(tab!=='Favorites'||liked.has(i))&&`${t.title} ${t.artist}`.toLowerCase().includes(query)).slice(0,expanded||query||tab==='Favorites'?5:3);$('#tracks').innerHTML=items.map(t=>{const i=tracks.indexOf(t);return `<div class="track"><div class="cover ${t.art}">${t.icon}</div><div class="track-info"><strong>${t.title}</strong><small>${t.artist}</small></div><button class="like ${liked.has(i)?'liked':''}" data-like="${i}" aria-label="${t.title}をお気に入り${liked.has(i)?'から削除':'に追加'}" aria-pressed="${liked.has(i)}">${liked.has(i)?'♥':'♡'}</button><button class="track-play" data-play="${i}" aria-label="${t.title}を再生">${current===i&&isPlaying?'Ⅱ':'▶'}</button></div>`}).join('');$('#empty').hidden=items.length>0;$('#favorite-count').innerHTML=`${128+liked.size}<small>曲</small>`}
function chart(previous=false){const values=previous?[2.5,3.8,4.1,3.2,4.8,3.4,2.9]:[3.6,4.8,3.9,5.5,3.7,4.9,4.1];$('#bars').innerHTML=values.map((v,i)=>`<div class="bar-wrap"><div class="bar" style="--height:${v/6*115}px;--bar:${['#b99bda','#efadc0','#efb981','#f5ce7c','#b6ca95','#9ec5df','#bea0db'][i]}" data-value="${v} h"></div><span>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</span></div>`).join('')}
function sound(start){if(!audio&&start){audio=new(window.AudioContext||window.webkitAudioContext)();gain=audio.createGain();gain.gain.value=0;gain.connect(audio.destination)}if(!audio)return;if(start){audio.resume();voices.forEach(v=>v.stop());voices=[];const root=tracks[current].hz;[root/2,root,root*1.25,root*1.5].forEach((frequency,i)=>{const o=audio.createOscillator();o.type='sine';o.frequency.value=frequency;const g=audio.createGain();g.gain.value=.14/(i+1);o.connect(g);g.connect(gain);o.start();voices.push(o)});gain.gain.setTargetAtTime(.23,audio.currentTime,.7)}else gain.gain.setTargetAtTime(0,audio.currentTime,.12)}
function play(index){const same=current===index;current=index;if(!same)seconds=0;isPlaying=same?!isPlaying:true;$('#player').hidden=false;$('#playing-title').textContent=tracks[index].title;$('#playing-artist').textContent=`${tracks[index].artist} · 試作用アンビエント音`;$('#toggle-play').textContent=isPlaying?'Ⅱ':'▶';sound(isPlaying);render();clearInterval(timer);timer=setInterval(()=>{if(isPlaying){seconds++;$('#elapsed').textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;$('.player-progress i').style.width=`${seconds%180/180*100}%`}},1000)}
$('#tracks').addEventListener('click',e=>{const like=e.target.closest('[data-like]'),p=e.target.closest('[data-play]');if(like){const i=+like.dataset.like;liked.has(i)?liked.delete(i):liked.add(i);render()}if(p)play(+p.dataset.play)});$('#search').addEventListener('input',render);$('#period').addEventListener('change',e=>chart(e.target.selectedIndex===1));$('#see-all').onclick=()=>{expanded=!expanded;$('#see-all').textContent=expanded?'閉じる ↗':'すべて見る ↗';render()};$('#play-something').onclick=()=>play(current??0);$('#mix').onclick=()=>{play(3);toast('Cozy afternoon — ゆっくりお楽しみください ♡')};$('#toggle-play').onclick=()=>play(current);$('#close-player').onclick=()=>{sound(false);isPlaying=false;clearInterval(timer);$('#player').hidden=true;render()};$('#notification').onclick=()=>toast('今週は8曲の新しい音楽に出会いました ♫');$('#settings').onclick=()=>toast('StreetMelody · パステルUI試作 v1');$('#upgrade').onclick=()=>$('#dialog').showModal();$('#dialog-close').onclick=$('#dialog-ok').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});$('#discover').onclick=()=>{expanded=true;tab='My Music';$('#search').value='';render();$('#list-title').textContent='Discover New Music';$('.recent').scrollIntoView({behavior:'smooth',block:'center'});toast('今日のおすすめを5曲セレクトしました ✦')};document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{tab=button.dataset.tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b===button));if(tab==='Favorites'||tab==='My Music'){expanded=true;$('#list-title').textContent=tab;render();$('.recent').scrollIntoView({behavior:'smooth',block:'center'})}else if(tab==='Playlists'){$('.mixes').scrollIntoView({behavior:'smooth',block:'center'});toast('あなたのデイリーミックスをどうぞ ♫')}else if(tab==='Activity'){$('.analytics').scrollIntoView({behavior:'smooth',block:'center'})}else{expanded=false;$('#list-title').textContent='Recently Played';render();window.scrollTo({top:0,behavior:'smooth'})}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}});chart();render();
